function summary(title,foreign){const labels=['已列账号数','本月总花销','本月成交金额','本月投入产出比','年度总广告支出','月度总广告支出'];const values=['9 个',foreign?'0':domesticAdTotal(),'0','0',foreign?'0':domesticAnnualTotal(),foreign?'0':domesticAdTotal()];return '<div class="panel summary '+(foreign?'foreign':'')+'"><h3>'+title+' · 正式数据</h3><small>'+(foreign?'未同步数字先显示0，采集到数据后自动更新':'广告费仅汇总已绑定账号，截至昨日；年度按当年1月1日起分月回补，缺失月份标为已采集部分；其余账号的0为未同步占位')+'</small><div class="summary-grid">'+labels.map((l,i)=>'<div class="summary-cell"><small>'+l+'</small><strong>'+values[i]+'</strong>'+metricComparison(l)+'</div>').join('')+'<div class="summary-cell"><small>A类商家</small><strong>0</strong><small>按客户等级 A 去重统计</small></div><div class="summary-cell"><small>已加数量</small><strong>0</strong><small>CRM 中已沟通客户数</small></div></div></div>';}
function group(title,platforms,foreign){return '<div class="platform-group"><h3>'+title+'</h3><div class="platforms '+(foreign?'foreign-platforms':'')+'">'+platforms.map(name=>'<div class="platform"><h3>'+name+'</h3>'+accountRows.map((a,i)=>a[0]===name?'<button data-account="'+i+'">'+a[1]+'</button>':'').join('')+'</div>').join('')+'</div></div>';}
function ledger(title,foreign){return '<div class="panel"><h3>'+title+'</h3><small>'+(foreign?'尚未接入自动同步': '已接入账号内容按逐日报表采集；未接入账号保留原快照；聚光广告按日同步，截至昨日')+' · 未同步数字先显示0，采集成功后自动更新</small><div class="scroll"><table><thead><tr>'+['平台','运营账号','负责人','总粉丝','本月增粉','昨日增粉','本月发布','本月花销','本月成交金额','投入产出比'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+accountRows.map((a,i)=>{if(i>=18||(i>=9)!==foreign)return '';return '<tr><td>'+a[0]+'</td><td>'+a[1]+(i===6&&hasFactorySnapshot()?' · 亦玩游乐玩具工厂':'')+'</td><td>'+accountOwner(a)+'</td><td>'+(creatorValue(a,'fans')??(i===6&&hasFactorySnapshot()?'__XHS_FANS__':'0'))+'</td>'+[creatorValue(a,'net_followers')??'0',creatorValue(a,'yesterday_net')??'0',creatorValue(a,'posts')??(i===6&&hasFactorySnapshot()?'12 条':'0'),(accountAdFee(a)==='待同步'?'¥0.00':accountAdFee(a)),'0','0'].map(v=>'<td>'+v+'</td>').join('')+'</tr>';}).join('')+'</tbody></table></div><small>粉丝值来源于创作后台粉丝页；已接入账号的发布、净增及内容指标来自逐日导出报表。总粉丝页面未注明截止时间，详情页显示采集时间；未接入账号的0为显示占位，登录和采集状态请看运营数据同步区。</small></div>';}

return '<div class="row between"><div><small>亦玩 Workplace / 部门 / 运营部</small><h2>工作总台</h2></div><span class="badge">统计范围：本月</span></div><div class="two">'+summary('内贸平台汇总',false)+summary('外贸平台汇总',true)+'</div><div class="panel"><h3>运营平台总览</h3><div class="two" style="margin-top:14px">'+group('内贸平台 · 3 个平台 / 9 个账号',['抖音','小红书','视频号'],false)+group('外贸平台 · 4 个平台 / 9 个账号',['Instagram','Facebook','YouTube','TikTok'],true)+'</div><div id="ga-account-detail" class="account-detail" hidden aria-live="polite"></div></div>'+ledger('内贸平台账号运营',false)+ledger('外贸平台账号运营',true);
